/// Operations on categories. It never commits: the caller owns the transaction.
public struct CategoryService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Category after checking it.
    @discardableResult
    public func createCategory(_ data: CategoryCreate) async throws -> CategoryRead {
        let values = Values(name: data.name.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Category()
            applyValues(&entity, values)
            return try await read(uow.categories.insert(entity))
        }
    }

    /// The Category with this key; notFound when there is none.
    public func getCategory(_ id: Int) async throws -> CategoryRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of categories, by primary key.
    public func listCategories(offset: Int, limit: Int) async throws -> Page<CategoryRead> {
        try await unitOfWork.categories.list(offset: offset, limit: limit).map(read)
    }

    /// Changes the given values of a Category.
    @discardableResult
    public func updateCategory(_ id: Int, _ changes: CategoryUpdate) async throws -> CategoryRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.categories.update(current))
        }
    }

    /// Deletes a Category.
    public func deleteCategory(_ id: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(try await uow.products.listByCategoryId(current.id!)).isEmpty {
                throw DomainError.conflict(entity: "Category", reason: "rows of products still point to it", fields: ["products"])
            }
            try await uow.categories.delete(current)
        }
    }

    /// The Category with this name, or nil.
    public func findCategoryByName(_ name: String) async throws -> CategoryRead? {
        try await unitOfWork.categories.findByName(name).map(read)
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var name: String?? = nil
}

/// Checks the values against the rules of the "categories" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Category?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.name ?? nil {
        if value.count > 60 {
            errors.append(FieldError("name", "is longer than 60 characters"))
        }
    } else if creating || values.name != nil {
        errors.append(FieldError("name", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Category", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Category?) async throws {
    if let name = values.name ?? current?.name,
       let other = try await uow.categories.findByName(name),
       current.map({ other.id != $0.id }) ?? true {
        throw DomainError.conflict(entity: "Category", reason: "name is already taken", fields: ["name"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Category?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Category, _ values: Values) {
    if let value = values.name { entity.name = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: CategoryUpdate) -> Values {
    Values(name: .some(changes.name))
}

/// The Category with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: Int) async throws -> Category {
    guard let row = try await uow.categories.findById(id) else {
        throw DomainError.notFound(entity: "Category", key: "\(id)")
    }
    return row
}

/// The Category as services return it.
fileprivate func read(_ entity: Category) -> CategoryRead {
    CategoryRead(id: entity.id!, name: entity.name!)
}

