fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Product?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Product, _ values: Values) {
    if let value = values.categoryId { entity.categoryId = value }
    if let value = values.name { entity.name = value }
    if let value = values.price { entity.price = value }
    if let value = values.status { entity.status = value }
    if let value = values.version { entity.version = value }
    if let value = values.deletedAt { entity.deletedAt = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: ProductUpdate) -> Values {
    Values(categoryId: .some(changes.categoryId), name: .some(changes.name), price: .some(changes.price), status: .some(changes.status), version: .some(changes.version), deletedAt: .some(changes.deletedAt))
}

